<style>
.task-editor{border:1px solid #dde7e1;border-radius:16px;overflow:hidden;background:#fff}.task-editor:focus-within{border-color:#8bb5a3;box-shadow:0 0 0 4px #77ae9318}.task-editor-toolbar{display:flex;flex-wrap:wrap;gap:4px;padding:10px;background:#f4f8f6;border-bottom:1px solid #e4ece7}.task-editor-toolbar button{border:0;border-radius:8px;padding:7px 10px;color:#637c70;font-size:12px;display:flex;gap:6px;align-items:center}.task-editor-toolbar button:hover,.task-editor-toolbar button[aria-pressed=true]{background:#e0ede6;color:#346b53}.task-editor-toolbar button:focus-visible{outline:2px solid #6a9d85;outline-offset:1px}.task-editor textarea,.task-field .task-editor textarea{display:block;border:0;border-radius:0;background:#fff;box-shadow:none;width:100%;padding:18px;resize:vertical;font-size:14px;line-height:1.8}.task-editor textarea[hidden]{display:none}.task-editor-help{padding:10px 16px!important;margin:0!important;background:#fafcfb;color:#86968e;font-size:11px!important}.task-editor [data-preview-body]{padding:20px;min-height:250px}.task-rich-text{overflow-wrap:anywhere;line-height:1.9;color:#43554d;font-size:14px}.task-rich-text p{margin:0 0 12px}.task-rich-text ul{list-style:disc;padding-left:24px}.task-rich-text ol{list-style:decimal;padding-left:24px}.task-rich-text pre{background:#202d2a;color:#e1f1e9;border-radius:12px;padding:18px;overflow:auto;margin:14px 0;white-space:pre}.task-rich-text code{font-family:monospace;background:#edf3ef;padding:2px 5px;border-radius:4px}.task-rich-text pre code{background:none;padding:0}.task-rich-text blockquote{border-left:3px solid #92b8a4;padding-left:16px;color:#7a8a82;margin:14px 0}.task-rich-text a{color:#397c64;text-decoration:underline}.task-rich-text h1,.task-rich-text h2,.task-rich-text h3{font-weight:700;font-size:1.2em;margin:16px 0}
</style>